package glitch

import data.glitch_lib

password_attrs := {
    "password",
    "passphrase",
    "secret",
    "pwd",
    "db_password",
    "admin_password",
    "api_key",
    "connection_string",
    "initial_password",
    "master_password",
    "root_password",
    "authentication"
}

check_empty_password(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Null"
}

check_connection_string_empty(value) {
    value.ir_type == "String"
    regex.match(".*(?:pwd|password)=\\s*[;&@].*", value.value)
} else {
    value.ir_type == "String"
    regex.match(".*(?:pwd|password)=\\s*$", value.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]

    attr.name == password_attrs[_]

    check_empty_password(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password configuration detected - Password fields should not be empty or null. (CWE-258)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]

    attr.name == "connection_string"

    check_connection_string_empty(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in connection string detected - Connection strings should not contain empty password parameters. (CWE-258)"
    }
}

