package glitch

import data.glitch_lib

# Define patterns for identifying password-related attributes
password_patterns := {
    "password",
    "passphrase",
    "secret",
    "pwd",
    "key",
    "pw",
    "credential",
    "token"
}

# Helper to check if an attribute name implies a secret
is_secret_name(name) {
    lower_name := lower(name)
    glitch_lib.contains(lower_name, password_patterns[_])
}

# Helper to check if a value is an empty password
# Excludes 'Null' to avoid false positives on explicit nil defaults (e.g., Chef)
is_empty_password(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Undef"
}

# Rule to detect empty passwords in Variables (Ansible, Chef)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_secret_name(var.name)
    is_empty_password(var.value)

    result := {
        "type": "sec_empty_pass",
        "element": var,
        "path": parent.path,
        "description": "Empty password configuration detected - Password fields should not be empty or undefined. (CWE-258)"
    }
}

# Rule to detect empty passwords in Attributes (Puppet)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    is_secret_name(attr.name)
    is_empty_password(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password configuration detected - Password fields should not be empty or undefined. (CWE-258)"
    }
}

# Rule to detect empty passwords in connection strings
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    attr.name == "connection_string"
    check_connection_string_empty(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in connection string detected - Connection strings should not contain empty password parameters. (CWE-258)"
    }
}

# Helper to check connection string patterns
